package main

// balatroc_syms_test.go — the anti-drift layer. Every gate address comes
// from build/board.map of the tap under test; pass-era hardcoded consts are
// retired. Maps are regenerated by build.sh on every compile, so gates and
// tape can never disagree again.

import (
	"fmt"
	"os"
	"regexp"
	"sync"
)

var (
	balMapOnce sync.Once
	balMap     map[string]uint16
)

func balSyms() map[string]uint16 {
	balMapOnce.Do(func() {
		balMap = map[string]uint16{}
		raw, err := os.ReadFile("/root/nerve-workspace/demos/balatroc-c/build/board.map")
		if err != nil {
			panic(fmt.Sprintf("balSyms: no board.map: %v", err))
		}
		re := regexp.MustCompile(`_(\w+)\s+=\s+\$([0-9A-Fa-f]{4})`)
		for _, m := range re.FindAllStringSubmatch(string(raw), -1) {
			var v uint64
			fmt.Sscanf(m[2], "%x", &v)
			balMap[m[1]] = uint16(v)
		}
	})
	return balMap
}

func balSym(name string) uint16 {
	v, ok := balSyms()[name]
	if !ok {
		panic(fmt.Sprintf("balSym: symbol %q not in board.map", name))
	}
	return v
}

/* PASS 65: paint_stats and its tables moved OFF core onto the PAGES
 * (stack-room law). balPageSym resolves PAGE GAME local symbols from
 * build/page_game.map; the caller must have bank 0 windowed at $C000
 * before calling one. */
var (
	balPageMapOnce sync.Once
	balPageMap     map[string]uint16
)

func balPageSym(name string) uint16 {
	balPageMapOnce.Do(func() {
		balPageMap = map[string]uint16{}
		raw, err := os.ReadFile("/root/nerve-workspace/demos/balatroc-c/build/page_game.map")
		if err != nil {
			panic(fmt.Sprintf("balPageSym: no page_game.map: %v", err))
		}
		re := regexp.MustCompile(`_(\w+)\s+=\s+\$([0-9A-Fa-f]{4})`)
		for _, m := range re.FindAllStringSubmatch(string(raw), -1) {
			var v uint64
			fmt.Sscanf(m[2], "%x", &v)
			balPageMap[m[1]] = uint16(v)
		}
	})
	v, ok := balPageMap[name]
	if !ok {
		panic(fmt.Sprintf("balPageSym: symbol %q not in page_game.map", name))
	}
	return v
}
